#!/usr/bin/env bash
# Launch one stage with configs generated by configure.py.
set -euo pipefail
snapshot_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
stage="${1:-}"
case "$stage" in
  returns) entry="examples/offline_rl/advantage_labeling/recap/process/compute_returns.py" ;;
  value) entry="examples/offline_rl/advantage_labeling/recap/train_value.py" ;;
  advantages) entry="examples/offline_rl/advantage_labeling/recap/process/compute_advantages.py" ;;
  policy) entry="examples/offline_rl/policy_optimization/cfg_rl/train_cfg.py" ;;
  *) echo 'Usage: bash scripts/run_stage.sh {returns|value|advantages|policy} [Hydra overrides...]' >&2; exit 2 ;;
esac
shift
train_python="${TRAIN_PYTHON:-python}"
config_dir="${RECAP_CONFIG_DIR:-$snapshot_root/configs/local}"
config_dir="$(cd "$config_dir" && pwd)"
test -f "$config_dir/$stage.yaml"
export REPO_PATH="$snapshot_root/RLinf"
export PYTHONPATH="$REPO_PATH:$snapshot_root/third_party/training${PYTHONPATH:+:$PYTHONPATH}"
export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-0,1}"
export JAX_PLATFORMS=cpu USE_TF=0 TOKENIZERS_PARALLELISM=false
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1
export PYTHONUNBUFFERED=1 HYDRA_FULL_ERROR=1 RAY_ADDRESS=local
cd "$REPO_PATH"
if [[ "$stage" == advantages ]]; then
  exec "$train_python" -m torch.distributed.run --standalone --nproc_per_node="${RECAP_NPROC:-2}" \
    "$entry" --config-path "$config_dir" --config-name "$stage" "$@"
else
  exec "$train_python" "$entry" --config-path "$config_dir" --config-name "$stage" "$@"
fi

